// Combiner et formater les informations restaurant
const items = $input.all();
const location = items[0]?.json || {};
const account = items[1]?.json || {};

// Formater les horaires d'ouverture
const formatOpeningHours = (hours) => {
  if (!hours) return null;

  const days = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday'];
  const daysFr = ['Lundi', 'Mardi', 'Mercredi', 'Jeudi', 'Vendredi', 'Samedi', 'Dimanche'];

  return days.map((day, index) => {
    const dayHours = hours[day];
    if (!dayHours || dayHours.length === 0) {
      return { day: daysFr[index], status: 'Fermé', slots: [] };
    }
    return {
      day: daysFr[index],
      status: 'Ouvert',
      slots: dayHours.map(slot => `${slot.from} - ${slot.to}`)
    };
  });
};

// Vérifier si le restaurant est actuellement ouvert
const isCurrentlyOpen = (hours) => {
  if (!hours) return { open: false, message: 'Horaires non disponibles' };

  const now = new Date();
  const days = ['sunday', 'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday'];
  const currentDay = days[now.getDay()];
  const currentTime = now.toTimeString().slice(0, 5);

  const todayHours = hours[currentDay];
  if (!todayHours || todayHours.length === 0) {
    return { open: false, message: 'Fermé aujourd\'hui' };
  }

  for (const slot of todayHours) {
    if (currentTime >= slot.from && currentTime <= slot.to) {
      return { open: true, message: `Ouvert jusqu'à ${slot.to}` };
    }
  }

  // Trouver le prochain créneau
  const nextSlot = todayHours.find(slot => currentTime < slot.from);
  if (nextSlot) {
    return { open: false, message: `Fermé, ouvre à ${nextSlot.from}` };
  }

  return { open: false, message: 'Fermé pour aujourd\'hui' };
};

const restaurantInfo = {
  name: location.name || account.name || 'Restaurant',
  id: location.id,
  account_id: account.id,

  contact: {
    phone: location.phone || '',
    email: location.email || account.email || '',
    website: location.website || ''
  },

  address: {
    street: location.address_1 || '',
    street2: location.address_2 || '',
    city: location.city || '',
    postal_code: location.postal_code || '',
    country: location.country || 'FR',
    full_address: [
      location.address_1,
      location.address_2,
      `${location.postal_code} ${location.city}`,
      location.country
    ].filter(Boolean).join(', ')
  },

  coordinates: {
    latitude: location.latitude || null,
    longitude: location.longitude || null
  },

  opening_hours: formatOpeningHours(location.opening_hours),
  current_status: isCurrentlyOpen(location.opening_hours),

  services: {
    delivery: location.delivery_enabled !== false,
    collection: location.collection_enabled !== false,
    eat_in: location.eat_in_enabled || false
  },

  currency: location.currency || 'EUR',
  timezone: location.timezone || 'Europe/Paris',

  metadata: {
    created_at: location.created_at,
    catalog_id: location.catalog_id,
    customer_list_id: location.customer_list_id
  }
};

return { json: restaurantInfo };
